from __future__ import annotations

from ...base.client import BaseClient


class RecentlyMethods(BaseClient):
    async def wim_recently_setAttentionAttribute(self, sn: str, value: int | str = 1) -> dict:
        """
        Метод для отметки чата как непрочитанного
        """
        return await self.post(
            "wim/recently/setAttentionAttribute",
            data={
                "sn": sn,
                "value": value,
                "aimsid": self.aimsid,
                "f": "json",
                "r": self.getReqId(),
            },
        )
